use std::collections::HashSet;

/// Returns a new vector containing each distinct value from `nums` exactly once.
/// - No duplicates in the result.
/// - Every value that appears in `nums` appears in the result (set equality).
///
/// Order is preserved by keeping the first occurrence of each value.
pub fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    let mut seen: HashSet<i32> = HashSet::new();
    let mut res: Vec<i32> = Vec::with_capacity(nums.len());

    for x in nums {
        if seen.insert(x) {
            res.push(x);
        }
    }
    res
}

